/// Shared helpers for the interop fixture tests.
///
/// The expected JSON is generated by `tool/interop/gen_expected.py` (pyarrow)
/// and committed under `test/fixtures/interop/expected/`.
library;

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:parquet/parquet.dart';
import 'package:parquet/src/util/int64.dart';
import 'package:test/test.dart';

import '../../tool/interop/interop_canonical.dart';

const String interopFixtureRoot = 'test/fixtures/interop';
const String interopManifestPath = '$interopFixtureRoot/expected/manifest.json';

/// One fixture plus its pyarrow-derived expectation document.
final class ExpectedFixture {
  ExpectedFixture(this.doc, this.manifestEntry);

  final Map<String, dynamic> doc;
  final Map<String, dynamic> manifestEntry;

  String get file => doc['file'] as String;
  String get path => '$interopFixtureRoot/$file';
  String get kind => doc['kind'] as String;
  String get expectedPath =>
      '$interopFixtureRoot/${manifestEntry['expected'] as String}';

  Map<String, dynamic> get meta => doc['meta'] as Map<String, dynamic>;
  List<Map<String, dynamic>> get leaves =>
      (doc['leaves'] as List<dynamic>).cast<Map<String, dynamic>>();
  List<Map<String, dynamic>> get columns =>
      (doc['columns'] as List<dynamic>).cast<Map<String, dynamic>>();

  Uint8List readBytes() => File(path).readAsBytesSync();

  ParquetReader open() => ParquetReader.fromBytes(readBytes());
}

/// Loads every expected fixture listed in the committed manifest.
List<ExpectedFixture> loadExpectedFixtures() {
  final manifest = jsonDecode(
    File(interopManifestPath).readAsStringSync(),
  ) as Map<String, dynamic>;
  final entries = (manifest['fixtures'] as List<dynamic>)
      .cast<Map<String, dynamic>>();
  return <ExpectedFixture>[
    for (final entry in entries)
      ExpectedFixture(
        jsonDecode(
          File('$interopFixtureRoot/${entry['expected']}').readAsStringSync(),
        ) as Map<String, dynamic>,
        entry,
      ),
  ];
}

/// Asserts schema, row counts, column classes and value checksums/samples.
void verifyFixtureValues(ExpectedFixture fixture) {
  final reason = fixture.file;
  final reader = fixture.open();
  final meta = fixture.meta;
  expect(reader.numRows, meta['rows'], reason: '$reason numRows');
  expect(
    reader.numRowGroups,
    meta['row_groups'],
    reason: '$reason numRowGroups',
  );
  expect(reader.createdBy, meta['created_by'], reason: '$reason createdBy');

  final expectedLeaves = fixture.leaves;
  expect(
    reader.schema.columns.length,
    expectedLeaves.length,
    reason: '$reason leaf count',
  );
  for (var i = 0; i < expectedLeaves.length; i++) {
    final expected = expectedLeaves[i];
    final actual = reader.schema.columns[i];
    final at = '$reason leaf[$i] ${expected['path']}';
    expect(actual.dotPath, expected['path'], reason: '$at path');
    expect(
      actual.physicalType.name,
      expected['physical'],
      reason: '$at physical',
    );
    expect(
      actual.typeLength,
      expected['type_length'],
      reason: '$at typeLength',
    );
    expect(
      actual.logicalType?.kind.name,
      expected['logical'],
      reason: '$at logical',
    );
    expect(actual.maxDefLevel, expected['max_def'], reason: '$at maxDef');
    expect(actual.maxRepLevel, expected['max_rep'], reason: '$at maxRep');
    expect(actual.scale, expected['scale'], reason: '$at scale');
    expect(actual.precision, expected['precision'], reason: '$at precision');
  }

  final table = reader.readTableSync();
  final expectedColumns = fixture.columns;
  expect(table.numRows, reader.numRows, reason: '$reason table rows');
  expect(table.columns.map((column) => column.name).toList(), <String>[
    for (final column in expectedColumns) column['name'] as String,
  ], reason: '$reason column names');

  for (var i = 0; i < expectedColumns.length; i++) {
    final expected = expectedColumns[i];
    final name = expected['name'] as String;
    final column = table[name];
    final at = '$reason column "$name"';
    expect(
      column.runtimeType.toString(),
      expected['dart_class'],
      reason: '$at dart class',
    );
    expect(column.length, expected['length'], reason: '$at length');
    expect(
      column.validity.nullCount,
      expected['null_count'],
      reason: '$at null count',
    );
    expect(
      columnChecksum(column),
      expected['checksum'],
      reason: '$at checksum',
    );
    final sampleRows = (expected['sample_rows'] as List<dynamic>).cast<int>();
    final samples = (expected['samples'] as List<dynamic>).cast<String>();
    expect(sampleRows.length, samples.length, reason: '$at sample shape');
    for (var s = 0; s < sampleRows.length; s++) {
      expect(
        canonicalJson(canonicalColumnValue(column, sampleRows[s])),
        samples[s],
        reason: '$at row ${sampleRows[s]}',
      );
    }
  }
}

/// Asserts that [fixture] fails with the recorded typed ParquetException.
void verifyFixtureThrows(ExpectedFixture fixture) {
  final type =
      fixture.doc['exception'] as String? ??
      (fixture.kind == 'unsupported'
          ? 'ParquetUnsupportedException'
          : 'ParquetException');
  final bytes = fixture.readBytes();
  expect(
    () {
      final reader = ParquetReader.fromBytes(bytes);
      reader.readTableSync();
    },
    throwsA(_parquetMatcher(type)),
    reason: '${fixture.file} should throw $type',
  );
}

Matcher _parquetMatcher(String type) {
  switch (type) {
    case 'ParquetUnsupportedException':
      return isA<ParquetUnsupportedException>();
    case 'ParquetFormatException':
      return isA<ParquetFormatException>();
    default:
      return isA<ParquetException>();
  }
}

/// Builds a small valid flat Parquet file for fuzz seeds.
Uint8List buildFuzzSeed() {
  final schema =
      (ParquetSchemaBuilder()
            ..addInt64('id', nullable: false)
            ..addBinary('name', utf8: true)
            ..addFloat64('score')
            ..addBoolean('flag'))
          .build();
  final rows = 64;
  final ids = Int64Buffer(rows);
  final scores = Float64List(rows);
  final bits = Uint8List((rows + 7) >> 3);
  final validity = Validity(rows);
  final data = <int>[];
  final offsets = Uint32List(rows + 1);
  for (var i = 0; i < rows; i++) {
    ids.setInt(i, i * 3 - 7);
    scores[i] = i.isEven ? i / 4.0 : -i / 8.0;
    if (i % 7 != 0) {
      bits[i >> 3] |= 1 << (i & 7);
    } else {
      validity.setNull(i);
    }
    final text = utf8.encode('row-$i');
    data.addAll(text);
    offsets[i + 1] = data.length;
  }
  final table = ParquetTable(
    schema: schema,
    columns: <ParquetColumn>[
      Int64Column(name: 'id', values: ids, validity: Validity(rows)),
      BinaryColumn(
        name: 'name',
        data: Uint8List.fromList(data),
        offsets: offsets,
        validity: Validity(rows),
        isUtf8: true,
      ),
      Float64Column(name: 'score', values: scores, validity: Validity(rows)),
      BooleanColumn(name: 'flag', bits: bits, validity: validity),
    ],
    numRows: rows,
  );
  return writeParquetTable(
    table,
    options: const ParquetWriterOptions(
      compression: CompressionType.snappy,
      pageSize: 128,
    ),
  );
}

/// Little-endian int helper used by fuzz tests.
int readUint32LE(Uint8List bytes, int offset) =>
    bytes[offset] |
    (bytes[offset + 1] << 8) |
    (bytes[offset + 2] << 16) |
    (bytes[offset + 3] << 24);

void writeUint32LE(Uint8List bytes, int offset, int value) {
  bytes[offset] = value & 0xFF;
  bytes[offset + 1] = (value >> 8) & 0xFF;
  bytes[offset + 2] = (value >> 16) & 0xFF;
  bytes[offset + 3] = (value >> 24) & 0xFF;
}

/// Footer start offset for a well-formed Parquet buffer.
int footerStart(Uint8List bytes) {
  final length = readUint32LE(bytes, bytes.length - 8);
  return bytes.length - 8 - length;
}
